import math
    import random
    import time

    LANGUAGE_WRAPPER = 'A city is modeled as an {rows}×{cols} square grid of blocks. The city adopts a k‑tuple total domination regulation: for every block in the grid (including blocks that host a booth), at least {k} of its four orthogonally adjacent blocks (up, down, left, right) must contain a security booth. Determine the minimum number of security booths required to meet the regulation throughout the city. After solving the problem, please output your final answer in the following format:\n### The final answer is: $\\boxed{<your answer>}$\nExample:\n### The final answer is: $\\boxed{123}$\nThe final answer should be given as precisely as possible (using LaTeX symbols such as \\sqrt, \\frac, \\pi, etc.). If the final answer involves a decimal approximation, it must be accurate to at least four decimal places.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Randomly generate a grid with modest dimensions and k in {1,2}.
# We keep cols small to ensure verifier's DP is fast and exact.
# Retry until constraints are met.
for _ in range(100):
    rows = rng.randint(5, 8)
    cols = rng.randint(5, 7)
    # Prefer k=2 occasionally to increase difficulty, but ensure tractable sizes.
    k = 2 if rng.random() < 0.35 else 1
    # k must be at most the minimum degree of boundary nodes (which is 2); hence k in {1,2} is always feasible.
    # To keep DP manageable, limit when k=2 to cols <= 7 and rows <= 8 (already satisfied).
    if k == 2 and (rows > 8 or cols > 7):
        continue
    # Basic sanity: ensure the instance is non-trivial.
    if rows * cols >= 25:
        return {'rows': rows, 'cols': cols, 'k': k}
# Fallback deterministic instance if randomness fails (unlikely).
return {'rows': 6, 'cols': 6, 'k': 2}

    def verifier(assign):
# Verify types and domains, then compute the exact minimum using row-by-row DP.
# Return (True, answer) if valid; else (False, None).
try:
    rows = int(assign.get('rows', None))
    cols = int(assign.get('cols', None))
    k = int(assign.get('k', None))
except Exception:
    # Invalid types
    return (False, None)
# Domain checks
if rows is None or cols is None or k is None:
    # Missing fields
    return (False, None)
if not (isinstance(rows, int) and isinstance(cols, int) and isinstance(k, int)):
    return (False, None)
if rows < 2 or cols < 2:
    # Grid too small to have orthogonal neighbors meaningful
    return (False, None)
if k < 1 or k > 2:
    # We only support k in {1,2} to ensure feasibility and tractability.
    return (False, None)
# Exact DP for k-tuple total domination on an rows x cols grid with 4-neighbor adjacency.
# Variables: binary per cell indicating booth.
# Constraint for each cell v: sum of booths in its orthogonal neighbors >= k.
# We compute minimal sum of booths using row-by-row dynamic programming over bitmasks per row.
max_mask = 1 << cols
def popcount(x):
    return bin(x).count('1')
# Precompute left-right contributions for each mask at each column index.
lr = [[0] * cols for _ in range(max_mask)]
for m in range(max_mask):
    for c in range(cols):
        s = 0
        if c - 1 >= 0:
            s += (m >> (c - 1)) & 1
        if c + 1 < cols:
            s += (m >> (c + 1)) & 1
        lr[m][c] = s
# Helper to check row constraints using three consecutive rows: above (a), mid (b), below (c)
def row_ok(a_mask, b_mask, c_mask, k):
    # Check for each column: neighbors are left/right in b_mask, and vertical a_mask[c], c_mask[c]
    for j in range(cols):
        cnt = lr[b_mask][j]
        cnt += (a_mask >> j) & 1
        cnt += (c_mask >> j) & 1
        if cnt < k:
            return False
    return True
# Initialize DP with two-row frontier: states are (prev_row_mask, curr_row_mask) -> cost
dp = {}
for m0 in range(max_mask):
    for m1 in range(max_mask):
        # Top row (index 0) must be satisfied using (above=0, mid=m0, below=m1)
        if row_ok(0, m0, m1, k):
            dp[(m0, m1)] = popcount(m0) + popcount(m1)
# Transition for rows 2..rows-1
for r in range(2, rows):
    new_dp = {}
    for (m_prev2, m_prev1), cost in dp.items():
        # Try all possible masks for current row r
        for m_cur in range(max_mask):
            # The row r-1 must be satisfied using (above=m_prev2, mid=m_prev1, below=m_cur)
            if not row_ok(m_prev2, m_prev1, m_cur, k):
                continue
            ncost = cost + popcount(m_cur)
            key = (m_prev1, m_cur)
            if key not in new_dp or ncost < new_dp[key]:
                new_dp[key] = ncost
    dp = new_dp
    if not dp:
        # If dp becomes empty, no feasible solution (shouldn't happen for k<=2); still handle.
        return (False, None)
# Finalization: ensure last row (rows-1) is satisfied with below mask = 0
ans = None
for (m_prev2, m_prev1), cost in dp.items():
    if row_ok(m_prev2, m_prev1, 0, k):
        if ans is None or cost < ans:
            ans = cost
if ans is None:
    # No feasible solution found (shouldn't happen for k<=2)
    return (False, None)
# Basic lower bound sanity: total demand = k*rows*cols; a booth contributes at most 4 to this demand.
# Therefore ans >= ceil(k*rows*cols / 4)
import math
lb = math.ceil(k * rows * cols / 4)
if ans < lb:
    # This would indicate a bug in DP; enforce difficulty and correctness
    return (False, None)
return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

